package com.chatsystem.user.controller.account;import com.chatsystem.shared.model.status.ProfileVisibility;import com.chatsystem.shared.service.ProfileService;import com.chatsystem.shared.session.UserSession;import com.chatsystem.user.ui.DisabledControlSupport;import javafx.fxml.FXML;import javafx.scene.control.*;import javafx.scene.layout.StackPane;
public final class ProfileController{private final ProfileService profiles;private final UserSession session;@FXML private TextField displayNameField,usernameField,bioField;@FXML private ChoiceBox<ProfileVisibility> visibilityChoice;@FXML private Label accountFeedbackLabel,profileEmailLabel,memberSinceLabel,accountStatusLabel;@FXML private Button previewButton,avatarButton;@FXML private StackPane previewWrapper,avatarWrapper;public ProfileController(ProfileService p,UserSession s){profiles=p;session=s;}@FXML private void initialize(){var u=session.getCurrentUser();displayNameField.setText(u.getDisplayName());usernameField.setText(u.getUsername());bioField.setText(u.getBio());profileEmailLabel.setText(u.getEmail());memberSinceLabel.setText("Member since "+u.getCreatedAt());accountStatusLabel.setText(u.getStatus().toString());visibilityChoice.getItems().setAll(ProfileVisibility.values());visibilityChoice.setValue(u.getProfileVisibility());DisabledControlSupport.install(previewButton,previewWrapper,"Public profile preview is unavailable because no public profile screen is supplied.");DisabledControlSupport.install(avatarButton,avatarWrapper,"Avatar selection is unavailable in the frontend-only demo.");}@FXML private void save(){var r=profiles.updateProfile(displayNameField.getText(),usernameField.getText(),bioField.getText(),visibilityChoice.getValue());accountFeedbackLabel.setText(r.isSuccess()?"Profile saved":r.errors().get(0).message());}}
